import { requireAdmin } from "@/lib/auth"; import { mergeSchema } from "@/lib/admin-validations"; import { computeWeightedRating, logAdminAction } from "@/lib/admin"; import { db } from "@/lib/db"; import { fail, handleApiError, ok } from "@/lib/http";
export async function POST(request: Request, { params }: { params: { id: string } }) { try { const actor = await requireAdmin(); const parsed = mergeSchema.safeParse(await request.json()); if (!parsed.success || parsed.data.targetVendorId === params.id) return fail("Choose another target vendor", 422); const [source, target] = await Promise.all([db.vendor.findUnique({ where: { id: params.id } }), db.vendor.findUnique({ where: { id: parsed.data.targetVendorId } })]); if (!source || !target) return fail("Vendor not found", 404); await db.$transaction(async (tx) => { const sourceReviews = await tx.review.findMany({ where: { vendorId: source.id } }); for (const review of sourceReviews) { const duplicate = await tx.review.findUnique({ where: { vendorId_userId: { vendorId: target.id, userId: review.userId } } }); if (duplicate) await tx.review.delete({ where: { id: review.id } }); else await tx.review.update({ where: { id: review.id }, data: { vendorId: target.id } }); } await tx.photo.updateMany({ where: { vendorId: source.id }, data: { vendorId: target.id } }); await tx.report.updateMany({ where: { vendorId: source.id }, data: { vendorId: target.id } }); await tx.vendor.update({ where: { id: source.id }, data: { status: "REJECTED", verificationNotes: `Merged into ${target.id}` } }); await logAdminAction(tx, { actorId: actor.id, action: "vendor_merged", entityType: "vendor", entityId: source.id, metadata: { targetVendorId: target.id } }); }); await computeWeightedRating(target.id); return ok({ sourceId: source.id, targetId: target.id }); } catch (error) { return handleApiError(error); } }
